import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(9 * 60, 17 * 60)


class FindGapsTests(unittest.TestCase):
    def test_gap_between_spans(self):
        worked = [Span(9 * 60, 12 * 60), Span(13 * 60, 17 * 60)]
        self.assertEqual(find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_edges_and_overlaps(self):
        worked = [Span(10 * 60, 12 * 60), Span(11 * 60, 13 * 60)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 13:00-17:00 (240 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_cover(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(8 * 60, 10 * 60)], OPEN)
